const TOPIC_GROUPS = [
  { group: 'Staatsfinanzen', topics: [
    { id: 'debt',    label: 'Schulden % BIP',   ind: 'GC.DOD.TOTL.GD.ZS',  unit: '%',     yLbl: '% des BIP',    dec: 1,
      title: 'Staatsverschuldung (% des BIP)',
      body: 'Die Staatsverschuldung als Anteil am Bruttoinlandsprodukt (BIP) misst die gesamten Verbindlichkeiten eines Staates im Verhältnis zur jährlichen Wirtschaftsleistung. Werte über 60 % gelten in der EU als kritisch (Maastricht-Kriterium), über 90 % können laut manchen Ökonomen das Wachstum bremsen. Japan liegt dauerhaft über 200 % – ohne unmittelbare Krise, da die Schulden großteils im Inland gehalten werden.',
      source: 'Weltbank: GC.DOD.TOTL.GD.ZS' },
    { id: 'debtAbs', label: 'Schulden absolut', ind: '__debtAbs__',          unit: ' Mrd€', yLbl: 'Mrd. EUR',     dec: 0, euroFmt: true,
      title: 'Staatsverschuldung absolut (Mrd. EUR)',
      body: 'Die absolute Staatsverschuldung in Milliarden Euro. Sie wird berechnet als Schuldenquote × nominales BIP in USD, umgerechnet mit dem jeweiligen Jahresdurchschnitt des EUR/USD-Wechselkurses. Die USA haben die höchsten absoluten Schulden, obwohl ihre Quote deutlich unter Japan liegt.',
      source: 'Berechnet: Weltbank GC.DOD.TOTL.GD.ZS × NY.GDP.MKTP.CD ÷ EUR/USD' },
    { id: 'deficit', label: 'Haushaltsdefizit', ind: 'GC.BAL.CASH.GD.ZS',  unit: '% BIP', yLbl: '% des BIP',    dec: 1,
      title: 'Haushaltsdefizit (% des BIP)',
      body: 'Das Haushaltsdefizit zeigt, ob ein Staat mehr ausgibt als er einnimmt. Negative Werte = Defizit, positive = Überschuss. Das Maastricht-Kriterium erlaubt maximal -3 % BIP. In Krisen (2009, 2020) schießen Defizite durch Konjunkturpakete und Steuerausfälle massiv in die Höhe.',
      source: 'Weltbank: GC.BAL.CASH.GD.ZS' },
    { id: 'taxrev',  label: 'Steuereinnahmen',  ind: 'GC.TAX.TOTL.GD.ZS',  unit: '% BIP', yLbl: '% des BIP',    dec: 1,
      title: 'Steuereinnahmen (% des BIP)',
      body: 'Die Steuereinnahmen als Anteil am BIP zeigen die Fiskalkapazität eines Staates – also wie viel Spielraum die Regierung hat, öffentliche Güter zu finanzieren. Skandinavische Länder liegen oft über 40 %, die USA unter 20 %. Ein hoher Wert ermöglicht mehr Umverteilung, kann aber auch die private Investitionstätigkeit bremsen.',
      source: 'Weltbank: GC.TAX.TOTL.GD.ZS' },
    { id: 'interest', label: 'Zinsausgaben',    ind: 'GC.XPN.INTP.ZS',    unit: '% Ausg.', yLbl: '% der Ausg.', dec: 1,
      title: 'Zinsausgaben des Staates (% der Staatsausgaben)',
      body: 'Die Zinsausgaben zeigen, wie teuer die bestehenden Schulden den Staat tatsächlich kommen — gemessen als Anteil der gesamten Staatsausgaben. In Zeiten niedriger Zinsen (2012–2021) sanken diese Kosten trotz wachsender Schuldenberge. Mit dem Zinsanstieg ab 2022 steigen sie wieder stark – besonders für hochverschuldete Länder wie Italien oder Griechenland wird das zur Belastung.',
      source: 'Weltbank: GC.XPN.INTP.ZS' },
  ]},
  { group: 'Konjunktur & Preise', topics: [
    { id: 'gdp',     label: 'BIP-Wachstum',     ind: 'NY.GDP.MKTP.KD.ZG',  unit: '%',     yLbl: 'Wachstum %',   dec: 1,
      title: 'BIP-Wachstum (real, % p.a.)',
      body: 'Das reale BIP-Wachstum zeigt die Veränderung der Wirtschaftsleistung bereinigt um Inflation. Krisenmomente wie 2009 (Finanzkrise) und 2020 (COVID-19) sind als globale Einbrüche klar erkennbar. Entwicklungsländer wie Indien oder China wachsen strukturell schneller als reife Volkswirtschaften.',
      source: 'Weltbank: NY.GDP.MKTP.KD.ZG' },
    { id: 'gdpAbs',  label: 'BIP absolut',       ind: '__gdpAbs__',           unit: ' Mrd€', yLbl: 'Mrd. EUR',     dec: 0, euroFmt: true,
      title: 'Bruttoinlandsprodukt absolut (Mrd. EUR)',
      body: 'Das nominale BIP in Milliarden Euro zeigt die absolute Wirtschaftsgröße eines Landes. Die USA sind mit Abstand die größte Volkswirtschaft der Welt, gefolgt von China. Innerhalb der EU dominiert Deutschland. Alle USD-Werte werden mit dem jeweiligen Jahresdurchschnitt des EUR/USD-Wechselkurses in Euro umgerechnet.',
      source: 'Berechnet: Weltbank NY.GDP.MKTP.CD ÷ EUR/USD-Wechselkurs' },
    { id: 'infl',    label: 'Inflation',         ind: 'FP.CPI.TOTL.ZG',     unit: '%',     yLbl: '%',            dec: 1,
      title: 'Inflation (Verbraucherpreisindex, % p.a.)',
      body: 'Die Inflation misst den Anstieg des allgemeinen Preisniveaus. Zentralbanken wie die EZB streben rund 2 % p.a. an. Die Inflationswelle 2021–2023 nach COVID-19 und dem Ukraine-Krieg ist in fast allen Ländern deutlich sichtbar.',
      source: 'Weltbank: FP.CPI.TOTL.ZG' },
    { id: 'unemp',   label: 'Arbeitslosigkeit',  ind: 'SL.UEM.TOTL.ZS',     unit: '%',     yLbl: '%',            dec: 1,
      title: 'Arbeitslosenquote (% der Erwerbsbevölkerung)',
      body: 'Die Arbeitslosenquote gibt den Anteil der arbeitslosen Personen an der Erwerbsbevölkerung an. Deutschland hat dank dualer Ausbildung chronisch niedrige Werte; Südeuropa verzeichnete nach der Eurokrise 2010–2015 Spitzenwerte über 25 %.',
      source: 'Weltbank: SL.UEM.TOTL.ZS' },
    { id: 'gdppc',   label: 'BIP pro Kopf',      ind: 'NY.GDP.PCAP.CD',     unit: ' €',    yLbl: 'EUR',          dec: 0, euroPc: true,
      title: 'BIP pro Kopf (nominal, EUR)',
      body: 'Das nominale BIP pro Kopf in Euro zeigt den durchschnittlichen wirtschaftlichen Output pro Person. Alle USD-Werte werden mit dem Jahresdurchschnitts-Wechselkurs EUR/USD umgerechnet. Die Schweiz und Norwegen führen Europa, die USA liegen in absoluten Zahlen sehr hoch. Entwicklungsländer wie Indien liegen unter 2.000 €.',
      source: 'Berechnet: Weltbank NY.GDP.PCAP.CD ÷ EUR/USD-Wechselkurs' },
    { id: 'productivity', label: 'Produktivität', ind: 'SL.GDP.PCAP.EM.KD', unit: ' $',    yLbl: 'USD/Beschäftigter', dec: 0,
      title: 'Arbeitsproduktivität (BIP pro Beschäftigten, kons. USD)',
      body: 'Das BIP pro Beschäftigten misst die wirtschaftliche Leistung je Arbeitskraft und ist ein Kernindikator für Wettbewerbsfähigkeit. Hochproduktive Volkswirtschaften können höhere Löhne zahlen und bleiben international konkurrenzfähig. Länder wie die USA, Norwegen und die Schweiz führen global. Deutschland liegt solide, aber unter dem US-Niveau – u.a. wegen Teilzeitquote und weniger Wochenstunden.',
      source: 'Weltbank: SL.GDP.PCAP.EM.KD (BIP pro Beschäftigten, konst. 2017-USD)' },
    { id: 'realwage',  label: 'Reallohnwachstum', ind: '__realwage__',       unit: '%',     yLbl: '% p.a.',       dec: 1,
      title: 'Reallohnwachstum (% p.a.)',
      body: 'Das Reallohnwachstum zeigt, ob Löhne schneller als die Inflation steigen. In vielen Ländern ist BIP-Wachstum nicht bei den Arbeitnehmern angekommen. Deutschland erlebte nach 2000 ein "Lohndumping-Jahrzehnt" – erst ab ~2012 stiegen Reallöhne wieder. Datenquelle: ILO Global Wage Report, OECD.Stat. Hinweis: Vorzeichenwechsel sind normal, Jahresdaten teilweise interpoliert.',
      source: 'ILO Global Wage Report / OECD.Stat (Schätzwerte, interpoliert)' },
    { id: 'poverty',   label: 'Armutsquote',      ind: 'SI.POV.NAHC',        unit: '%',     yLbl: '% der Bev.',   dec: 1,
      title: 'Armutsquote (nationale Armutsgrenzen, % der Bevölkerung)',
      body: 'Die Armutsquote misst den Anteil der Bevölkerung unterhalb der national definierten Armutsgrenze. In der EU gilt typischerweise 60 % des Medianeinkommens als Schwelle (relative Armut). Entwicklungsländer verwenden absolute Grenzen (z.B. 2,15 $/Tag). Hinweis: Weltbank-Daten für diese Variable sind für viele Industrieländer lückenhaft – sie berichten an Eurostat statt an die Weltbank.',
      source: 'Weltbank: SI.POV.NAHC (nationale Armutslinien)' },
    { id: 'netmigration', label: 'Migrationssaldo', ind: 'SM.POP.NETM',      unit: '',      yLbl: 'Personen',     dec: 0, popFmt: true,
      title: 'Netto-Migrationssaldo (Personen, 5-Jahres-Perioden)',
      body: 'Der Netto-Migrationssaldo ist die Differenz aus Zu- und Abwanderung. Positive Werte = mehr Zuwanderer als Auswanderer. Deutschland und die USA sind traditionell Einwanderungsländer, während Südeuropa und osteuropäische Länder Netto-Auswanderer verzeichneten. Die Flüchtlingswelle 2015/16 ist in den deutschen Zahlen klar sichtbar. Hinweis: Weltbank-Daten kommen in 5-Jahres-Schritten.',
      source: 'Weltbank: SM.POP.NETM (Nettomigration, 5-Jahres-Perioden)' },
  ]},
  { group: 'Gesundheit', topics: [
    { id: 'physicians', label: 'Ärztedichte',     ind: 'SH.MED.PHYS.ZS',    unit: '/1k',   yLbl: 'Ärzte/1.000', dec: 2,
      title: 'Ärztedichte (Ärzte pro 1.000 Einwohner)',
      body: 'Die Ärztedichte ist ein Kernindikator der Gesundheitsversorgung. Europa liegt durchgehend hoch (3–5 Ärzte/1.000), mit Österreich und Griechenland an der Spitze der EU. Die USA haben eine moderate Dichte trotz sehr hoher Gesundheitsausgaben. Entwicklungsländer wie Indien liegen unter 1. Ein Mangel führt zu längeren Wartezeiten und schlechterer Prävention.',
      source: 'Weltbank: SH.MED.PHYS.ZS' },
    { id: 'hospitalbed', label: 'Krankenhausbetten', ind: 'SH.MED.BEDS.ZS', unit: '/1k',   yLbl: 'Betten/1.000', dec: 1,
      title: 'Krankenhausbetten pro 1.000 Einwohner',
      body: 'Krankenhausbetten pro 1.000 Einwohner zeigen die stationäre Versorgungskapazität. Japan und Deutschland führen mit über 12 bzw. 8 Betten/1.000 – deutlich über dem OECD-Schnitt (~4,5). Die USA haben trotz hoher Ausgaben wenig Betten (~2,9). COVID-19 hat die Relevanz dieser Kennzahl für Pandemieresilienz drastisch verdeutlicht.',
      source: 'Weltbank: SH.MED.BEDS.ZS' },
    { id: 'obesity',    label: 'Adipositasrate',   ind: 'SH.STA.OWGH.ZS',   unit: '%',     yLbl: '% der Erw.',  dec: 1,
      title: 'Adipositasrate (% der Erwachsenen mit BMI ≥ 30)',
      body: 'Die Adipositasrate misst den Anteil der Erwachsenen mit einem Body-Mass-Index von 30 oder höher. Die USA führen unter Industrieländern mit über 40 %, gefolgt von Australien und Kanada. Japan und Südkorea haben die niedrigsten Raten. Adipositas ist ein starker Prädiktor für Diabetes, Herzerkrankungen und Krebserkrankungen und belastet die Gesundheitssysteme massiv.',
      source: 'Weltbank: SH.STA.OWGH.ZS (WHO-Daten, nicht jährlich)' },
    { id: 'alcohol',    label: 'Alkoholkonsum',    ind: 'SH.ALC.PCAP.LI',   unit: ' L',    yLbl: 'Liter/Kopf',  dec: 1,
      title: 'Alkoholkonsum pro Kopf (Liter reiner Alkohol, Erwachsene)',
      body: 'Der Alkoholkonsum in Litern reinen Alkohols pro Kopf (15+) ist ein Indikator für Suchtprävention und Volksgesundheit. Europa – besonders Osteuropa, Tschechien, Deutschland und Österreich – liegt traditionell hoch. Muslimisch geprägte Länder verzeichnen nahezu null. Exzessiver Konsum korreliert stark mit Leberzirrhose, Herzkrankheiten und sozialen Kosten.',
      source: 'Weltbank/WHO: SH.ALC.PCAP.LI' },
    { id: 'tobacco',    label: 'Tabakkonsum',      ind: 'SH.PRV.SMOK.ZS',   unit: '%',     yLbl: '% Raucher',   dec: 1,
      title: 'Raucherquote (% der Bevölkerung 15+)',
      body: 'Die Raucherquote misst den Anteil der täglichen oder gelegentlichen Raucher an der erwachsenen Bevölkerung. Osteuropa und Griechenland haben traditionell hohe Quoten, Schweden und Kanada niedrige. Seit den 1990ern sinken die Quoten in fast allen entwickelten Ländern durch Aufklärung, Preiserhöhungen und Rauchverbote. Rauchen ist die größte vermeidbare Todesursache weltweit.',
      source: 'WHO/Weltbank: SH.PRV.SMOK.ZS (nicht jährlich verfügbar)' },
    { id: 'beer',     label: 'Bierkonsum',         ind: '__beer__',            unit: ' L',    yLbl: 'Liter/Kopf',  dec: 1, beerFmt: true,
      title: 'Bierkonsum pro Kopf (Liter/Jahr)',
      body: 'Der jährliche Pro-Kopf-Bierkonsum ist ein kultureller wie wirtschaftlicher Indikator. Tschechien führt die Weltrangliste mit über 180 Litern pro Kopf – mehr als doppelt so viel wie Deutschland oder Österreich (~80–100 L). Biermärkte sind ein bedeutender Wirtschaftsfaktor: Die Brauindustrie schafft Jobs, Tourismus und regionale Identität. Der Konsum sinkt in vielen westlichen Ländern durch Craft-Beer-Trends und Gesundheitsbewusstsein. Hinweis: Daten stammen aus Kirin-Bericht/Statista-Schätzungen, nicht aus der Weltbank.',
      source: 'Kirin Holdings Beer Consumption Report / Statista (Schätzwerte)' },
  ]},
  { group: 'Soziales & Ungleichheit', topics: [
    { id: 'gini',    label: 'Gini-Index',        ind: 'SI.POV.GINI',         unit: '',      yLbl: 'Gini (0–100)', dec: 1,
      title: 'Gini-Koeffizient (Einkommensungleichheit)',
      body: 'Der Gini-Koeffizient misst Einkommensungleichheit auf einer Skala von 0 (vollständige Gleichheit) bis 100. Skandinavien und Mitteleuropa liegen unter 30, die USA über 40, Lateinamerika oft über 50. Hinweis: Der Datensatz ist lückenhafter als andere Indikatoren.',
      source: 'Weltbank: SI.POV.GINI' },
    { id: 'hdi',     label: 'HDI',               ind: null,                  unit: '',      yLbl: 'HDI (0–1)',    dec: 3,
      title: 'Human Development Index (HDI)',
      body: 'Der HDI kombiniert Lebenserwartung, Bildungsniveau und Pro-Kopf-Einkommen. Er reicht von 0 bis 1 – Werte über 0,8 gelten als "sehr hoch". Hinweis: HDI-Daten werden hier als Schätzwerte auf Basis veröffentlichter UNDP-Jahreswerte dargestellt.',
      source: 'UNDP Human Development Reports (Schätzwerte)' },
    { id: 'lifeexp', label: 'Lebenserwartung',   ind: 'SP.DYN.LE00.IN',     unit: ' J',    yLbl: 'Jahre',        dec: 1,
      title: 'Lebenserwartung bei Geburt (Jahre)',
      body: 'Die Lebenserwartung bei Geburt ist ein zentraler Indikator für den Gesundheitszustand einer Bevölkerung. Sie ist in Westeuropa und Japan am höchsten (über 83 Jahre). COVID-19 verursachte 2020–2021 in vielen Ländern einen messbaren Rückgang. Langfristig steigt sie fast überall dank medizinischem Fortschritt.',
      source: 'Weltbank: SP.DYN.LE00.IN' },
    { id: 'healthexp', label: 'Gesundheitsausg.', ind: 'SH.XPD.CHEX.GD.ZS', unit: '% BIP', yLbl: '% des BIP',   dec: 1,
      title: 'Gesundheitsausgaben (% des BIP)',
      body: 'Die gesamten Gesundheitsausgaben (öffentlich + privat) als Anteil am BIP zeigen, wie viel eine Gesellschaft in Gesundheit investiert. Die USA geben mit über 17 % des BIP mit Abstand am meisten aus, erzielen aber im internationalen Vergleich keine entsprechend besseren Gesundheitsergebnisse. Deutschland liegt bei ca. 12 %.',
      source: 'Weltbank: SH.XPD.CHEX.GD.ZS' },
    { id: 'educexp', label: 'Bildungsausgaben',  ind: 'SE.XPD.TOTL.GD.ZS',  unit: '% BIP', yLbl: '% des BIP',   dec: 1,
      title: 'Bildungsausgaben (% des BIP)',
      body: 'Öffentliche Ausgaben für Bildung als Anteil am BIP sind ein Maß für die gesellschaftliche Investition in Humankapital. Skandinavische Länder investieren oft über 6 % des BIP. Höhere Bildungsausgaben korrelieren langfristig mit Produktivitätswachstum, Innovationskraft und niedrigerer Ungleichheit.',
      source: 'Weltbank: SE.XPD.TOTL.GD.ZS' },
  ]},
  { group: 'Demografie', topics: [
    { id: 'pop',     label: 'Bevölkerung',       ind: 'SP.POP.TOTL',         unit: '',      yLbl: 'Personen',     dec: 0, popFmt: true,
      title: 'Bevölkerungsgröße',
      body: 'Die Gesamtbevölkerung bestimmt Marktgröße, Arbeitskräftepotenzial und politisches Gewicht. China und Indien haben 2023 die Milliarden-Marke überquert – Indien hat China dabei überholt. Europa und Japan schrumpfen demografisch, was Rentenfinanzierung und Wachstumspotenzial unter Druck setzt.',
      source: 'Weltbank: SP.POP.TOTL' },
    { id: 'popgrowth', label: 'Bevölkerungswachstum', ind: 'SP.POP.GROW',   unit: '%',     yLbl: '% p.a.',       dec: 2,
      title: 'Bevölkerungswachstum (% p.a.)',
      body: 'Das jährliche Bevölkerungswachstum sinkt in entwickelten Volkswirtschaften gegen null oder wird negativ. Deutschland und Japan verzeichnen ohne Zuwanderung Schrumpfung. Hohe Wachstumsraten in Entwicklungsländern sind wirtschaftlich Chance und Herausforderung zugleich.',
      source: 'Weltbank: SP.POP.GROW' },
    { id: 'fertility', label: 'Geburtenrate',    ind: 'SP.DYN.TFRT.IN',     unit: '',      yLbl: 'Kinder/Frau',  dec: 2,
      title: 'Gesamtfruchtbarkeitsrate (Kinder pro Frau)',
      body: 'Die Gesamtfruchtbarkeitsrate gibt an, wie viele Kinder eine Frau im Laufe ihres Lebens im Durchschnitt bekommt. Zum Erhalt der Bevölkerungsgröße sind ca. 2,1 Kinder pro Frau nötig. Alle entwickelten Volkswirtschaften liegen darunter; Südkorea (~0,8) und einige EU-Länder verzeichnen historische Tiefstände.',
      source: 'Weltbank: SP.DYN.TFRT.IN' },
    { id: 'aged',    label: 'Anteil 65+',        ind: 'SP.POP.65UP.TO.ZS',   unit: '%',     yLbl: '% der Bev.',   dec: 1,
      title: 'Bevölkerungsanteil 65 Jahre und älter (%)',
      body: 'Der Altenquotient zeigt den Anteil der Menschen ab 65 an der Gesamtbevölkerung. Japan ist mit über 29 % das am stärksten gealterte Land der Welt. Ein hoher Anteil bedeutet wachsende Belastung für Rentensysteme und Gesundheitsversorgung, gleichzeitig sinkende Erwerbsbevölkerung.',
      source: 'Weltbank: SP.POP.65UP.TO.ZS' },
    { id: 'medage',  label: 'Durchschnittsalter', ind: 'SP.POP.DPND',        unit: ' J',    yLbl: 'Medianalter',  dec: 1,
      title: 'Medianalter der Bevölkerung (Jahre)',
      body: 'Das Medianalter ist der Alterswert, der die Bevölkerung in zwei gleich große Hälften teilt. Japan (~49 J.), Deutschland (~46 J.) und Italien (~47 J.) haben das höchste Medianalter der Welt. Junge Bevölkerungen (Indien ~28 J., Brasilien ~33 J.) haben mehr Arbeitskräftepotenzial, aber höheren Bedarf an Infrastruktur und Bildung. Hinweis: Weltbank führt keinen direkten Medianalter-Indikator – dieser wird aus dem Altersstruktur-Abhängigkeitsquotient approximiert.',
      source: 'Näherung via Weltbank SP.POP.DPND (Abhängigkeitsquotient als Proxy)' },
  ]},
  { group: 'Bildung & Innovation', topics: [
    { id: 'rdexp',    label: 'Forschungsausg. R&D', ind: 'GB.XPD.RSDV.GD.ZS', unit: '% BIP', yLbl: '% des BIP',   dec: 2,
      title: 'Forschungs- und Entwicklungsausgaben (% des BIP)',
      body: 'Die F&E-Ausgaben sind ein Schlüsselindikator für Innovationskraft und langfristiges Wachstumspotenzial. Israel und Südkorea führen global mit über 5 % des BIP. Deutschland und Österreich liegen mit ~3 % im oberen Mittelfeld. Länder mit höheren F&E-Ausgaben patentieren mehr, haben produktivere Wirtschaften und sind widerstandsfähiger gegen Strukturwandel.',
      source: 'Weltbank: GB.XPD.RSDV.GD.ZS' },
    { id: 'patents',  label: 'Patentanmeldungen',  ind: '__patents__',        unit: '/Mio',  yLbl: 'pro Mio Einw.', dec: 0,
      title: 'Patentanmeldungen pro Million Einwohner (PCT + national)',
      body: 'Patentanmeldungen pro Einwohner messen den Output des Innovationssystems. Japan und Südkorea führen deutlich vor Deutschland und der Schweiz. Viele Patente entstehen in wenigen Technologieclustern – die Zahl allein sagt wenig über Qualität. Trotzdem gilt: Länder mit hoher Patentdichte haben tendenziell stärkere Hightech-Exportbranchen. Daten: WIPO IP Statistics / Eurostat.',
      source: 'WIPO IP Statistics / Eurostat (Schätzwerte, interpoliert)' },
    { id: 'tertiary', label: 'Hochschulquote',     ind: 'SE.TER.ENRR',        unit: '%',     yLbl: '% Bruttoquote', dec: 1,
      title: 'Hochschulabschlussquote (Brutto-Einschreibungsquote)',
      body: 'Die Brutto-Einschreibungsquote im Tertiärbereich zeigt, welcher Anteil der altersrelevanten Bevölkerung ein Studium aufnimmt. Australien, die USA und Südkorea liegen über 100 % (durch Studenten aller Altersgruppen). Deutschland liegt mit dualer Ausbildungstradition niedriger als der OECD-Schnitt, was kein Nachteil sein muss. Höhere Quoten korrelieren mit Innovationskraft, aber auch mit Akademiker-Überschuss in manchen Ländern.',
      source: 'Weltbank: SE.TER.ENRR (Brutto-Einschreibungsquote Tertiärbereich)' },
    { id: 'pisaread', label: 'PISA Lesen',         ind: '__pisa_read__',       unit: ' Pkt',  yLbl: 'Punkte',       dec: 0, pisaFmt: true,
      title: 'PISA-Score Lesen (15-Jährige)',
      body: 'Der PISA-Lesetest der OECD misst die Lesekompetenz 15-jähriger Schüler alle drei Jahre. Der OECD-Durchschnitt liegt bei ~490 Punkten. Singapur, Japan und Estland führen regelmäßig. Deutschland liegt im Mittelfeld, während Österreich zuletzt unter den OECD-Schnitt fiel. Die Daten sind keine Jahresdaten sondern 3-Jahres-Erhebungen (2000, 2003, 2006 ...). Hinweis: Werte werden für Zwischenjahre interpoliert dargestellt.',
      source: 'OECD PISA (alle 3 Jahre, interpoliert für Darstellung)' },
    { id: 'pisamath', label: 'PISA Mathematik',    ind: '__pisa_math__',       unit: ' Pkt',  yLbl: 'Punkte',       dec: 0, pisaFmt: true,
      title: 'PISA-Score Mathematik (15-Jährige)',
      body: 'Der PISA-Mathematiktest misst Problemlösungskompetenz in quantitativen Kontexten. Ostasiatische Länder (Japan, Südkorea, China-Shanghai) dominieren dauerhaft. Innerhalb Europas führt die Schweiz, gefolgt von den Niederlanden und Estland. Deutschland verbesserte sich nach dem "PISA-Schock" 2001 signifikant. Österreich fiel zuletzt zurück. Die Scores sind 3-Jahres-Erhebungen, hier für die Darstellung interpoliert.',
      source: 'OECD PISA (alle 3 Jahre, interpoliert für Darstellung)' },
    { id: 'pisasci',  label: 'PISA Naturwiss.',    ind: '__pisa_sci__',        unit: ' Pkt',  yLbl: 'Punkte',       dec: 0, pisaFmt: true,
      title: 'PISA-Score Naturwissenschaften (15-Jährige)',
      body: 'Der PISA-Naturwissenschaftstest bewertet das Verständnis naturwissenschaftlicher Konzepte und die Fähigkeit, wissenschaftlich zu denken. Japan, Estland und Südkorea führen. Deutschland und Österreich liegen im OECD-Mittelfeld. Naturwissenschaftliche Grundkompetenz gilt als zentral für Innovationsfähigkeit, Klimabewusstsein und technologische Souveränität.',
      source: 'OECD PISA (alle 3 Jahre, interpoliert für Darstellung)' },
  ]},
  { group: 'Energie & Ressourcen', topics: [
    { id: 'co2',     label: 'CO₂ pro Kopf',      ind: 'EN.ATM.CO2E.PC',     unit: ' t',    yLbl: 'Tonnen/Kopf',  dec: 1,
      title: 'CO₂-Emissionen pro Kopf (Tonnen)',
      body: 'Die CO₂-Emissionen pro Kopf zeigen den durchschnittlichen Klimaabdruck pro Person. Australien, die USA und Kanada liegen traditionell sehr hoch (über 15 t), EU-Länder bei 6–9 t, Indien unter 2 t. Seit den 2000ern sinken die Werte in Industrieländern, steigen aber in Schwellenländern durch Industrialisierung. Hinweis: Weltbank-Daten enden bei 2021.',
      source: 'Weltbank: EN.ATM.CO2E.PC (Daten bis 2021)' },
    { id: 'renewables', label: 'Erneuerbare Energien', ind: 'EG.FEC.RNEW.ZS', unit: '%',   yLbl: '% Endenergie', dec: 1,
      title: 'Anteil erneuerbarer Energien am Endenergieverbrauch (%)',
      body: 'Der Anteil erneuerbarer Energien (Solar, Wind, Wasserkraft, Biomasse) am gesamten Endenergieverbrauch ist ein Kernindikator der Energiewende. Norwegen liegt durch Wasserkraft nahe 70 %, Deutschland hat in den letzten Jahren stark zugelegt. China investiert massiv – trotzdem bleibt der Anteil durch den schieren Energiehunger der Wirtschaft moderat.',
      source: 'Weltbank: EG.FEC.RNEW.ZS' },
    { id: 'nuclear',  label: 'Atomstrom %',        ind: 'EG.ELC.NUCL.ZS',    unit: '%',     yLbl: '% der Stromerzeugung', dec: 1,
      title: 'Atomstromanteil (% der Stromerzeugung)',
      body: 'Der Anteil der Kernenergie an der gesamten Stromerzeugung zeigt die Rolle der Atomkraft im Energiemix. Frankreich deckt über 70 % seines Stroms durch Kernkraft – Weltrekord. Deutschland lag früher bei ~30 % und stieg 2023 komplett aus. Japan fuhr nach Fukushima 2011 fast alle Reaktoren ab, fährt sie aber schrittweise wieder hoch. Tschechien und die Slowakei sind stark von Kernenergie abhängig.',
      source: 'Weltbank: EG.ELC.NUCL.ZS' },
    { id: 'energyimport', label: 'Energieabhängigkeit', ind: 'EG.IMP.CONS.ZS', unit: '%',  yLbl: '% des Energieverbrauchs', dec: 1,
      title: 'Energieabhängigkeit vom Ausland (% des Energieverbrauchs)',
      body: 'Dieser Indikator zeigt, welcher Anteil des Energieverbrauchs durch Nettoimporte gedeckt wird. Länder ohne eigene Ressourcen wie Japan (~90 %) oder viele EU-Staaten sind stark abhängig. Norwegen hat negative Werte (Nettoexporteur). Die Abhängigkeit von russischem Gas rückte nach dem Ukraine-Krieg 2022 stark in den Fokus – besonders für Deutschland und Österreich.',
      source: 'Weltbank: EG.IMP.CONS.ZS' },
    { id: 'water',    label: 'Wasserverbrauch',    ind: 'ER.H2O.FWTL.ZS',    unit: '%',     yLbl: '% Süßwasserressourcen', dec: 1,
      title: 'Süßwasserentnahme (% der Süßwasserressourcen)',
      body: 'Die Süßwasserentnahme als Anteil der verfügbaren Ressourcen zeigt Wasserknappheit und -stress. Länder über 25 % gelten als "wasserstressgefährdet", über 75 % als "extrem wasserarm". Spanien und Indien kämpfen mit chronischem Wasserstress. Deutschland und Österreich nutzen weniger als 20 % ihrer Ressourcen. Hinweis: Weltbank-Daten für diesen Indikator sind selten jährlich verfügbar.',
      source: 'Weltbank: ER.H2O.FWTL.ZS (nicht jährlich)' },
    { id: 'plastic',  label: 'Plastikmüll/Kopf',  ind: '__plastic__',         unit: ' kg',   yLbl: 'kg/Kopf/Jahr', dec: 1, plasticFmt: true,
      title: 'Plastikmüll pro Kopf (kg/Jahr)',
      body: 'Der Pro-Kopf-Plastikmüll zeigt Produktions- und Konsummuster sowie Recyclingeffizienz. Australien, die USA und Deutschland erzeugen pro Kopf sehr viel Plastikmüll (>80 kg/Jahr). Asiatische Länder liegen teilweise niedriger im Verbrauch, haben aber größere Umweltprobleme durch schlechtes Abfallmanagement. Hinweis: Systematische Jahresdaten fehlen – Werte basieren auf OECD/Eurostat-Schätzungen und werden interpoliert.',
      source: 'OECD/Eurostat Plastikmüll-Schätzungen (interpoliert)' },
    { id: 'forestarea', label: 'Waldfläche',     ind: 'AG.LND.FRST.ZS',      unit: '%',     yLbl: '% der Landfläche', dec: 1,
      title: 'Waldfläche (% der Landfläche)',
      body: 'Die Waldfläche als Anteil an der Gesamtlandfläche ist ein Indikator für Ökosystemgesundheit und CO₂-Speicherkapazität. Brasilien ist durch den Amazonas dominiert, verliert aber jährlich Waldfläche durch Abholzung. Japan und Schweden sind stark bewaldet. Deutschland hat seinen Waldanteil durch Dürre und Borkenkäfer in den 2010ern deutlich reduziert.',
      source: 'Weltbank: AG.LND.FRST.ZS' },
  ]},
  { group: 'Handel & Außenwirtschaft', topics: [
    { id: 'exports',  label: 'Exporte % BIP',    ind: 'NE.EXP.GNFS.ZS',      unit: '% BIP', yLbl: '% des BIP',    dec: 1,
      title: 'Exporte von Waren und Dienstleistungen (% des BIP)',
      body: 'Der Exportanteil am BIP misst die Außenhandelsorientierung einer Volkswirtschaft. Kleine, offene Volkswirtschaften wie die Schweiz, Belgien oder die Niederlande liegen über 80 %. Deutschland (~47 %) ist als Exportnation bekannt. Große Binnenmärkte wie die USA oder Indien haben niedrigere Quoten.',
      source: 'Weltbank: NE.EXP.GNFS.ZS' },
    { id: 'imports',  label: 'Importe % BIP',    ind: 'NE.IMP.GNFS.ZS',      unit: '% BIP', yLbl: '% des BIP',    dec: 1,
      title: 'Importe von Waren und Dienstleistungen (% des BIP)',
      body: 'Die Importquote zeigt, wie stark eine Volkswirtschaft von ausländischen Gütern und Dienstleistungen abhängt. Im Zusammenspiel mit der Exportquote ergibt sich die Handelsbilanz. Länder mit dauerhaft hohen Importen bei niedrigen Exporten häufen Außenhandelsdefizite an.',
      source: 'Weltbank: NE.IMP.GNFS.ZS' },
    { id: 'cab',      label: 'Leistungsbilanz',  ind: 'BN.CAB.XOKA.GD.ZS',   unit: '% BIP', yLbl: '% des BIP',    dec: 1,
      title: 'Leistungsbilanzsaldo (% des BIP)',
      body: 'Die Leistungsbilanz fasst Handel, Dienstleistungen, Kapitalerträge und Transfers zusammen. Ein Überschuss bedeutet, dass ein Land mehr "exportiert" als es "importiert" – Deutschland hat chronisch hohe Überschüsse (~7 % BIP), was international Kritik provoziert. Defizite zeigen Abhängigkeit von ausländischem Kapital.',
      source: 'Weltbank: BN.CAB.XOKA.GD.ZS' },
    { id: 'fdi',      label: 'Direktinvestitionen', ind: 'BX.KLT.DINV.WD.GD.ZS', unit: '% BIP', yLbl: '% des BIP', dec: 1,
      title: 'Ausländische Direktinvestitionen, Zuflüsse (% des BIP)',
      body: 'Ausländische Direktinvestitionen (FDI) zeigen, wie attraktiv ein Land für internationale Unternehmen als Produktions- oder Marktstandort ist. Hohe Werte deuten auf Vertrauen in Rechtssicherheit, Infrastruktur und Marktpotenzial hin. Irland und Luxemburg haben durch ihre Steuerpolitik strukturell sehr hohe Werte.',
      source: 'Weltbank: BX.KLT.DINV.WD.GD.ZS' },
  ]},
];

