const PISA_YEARS = [2000,2003,2006,2009,2012,2015,2018,2022];

function getPISA(code, type) {
  const d = PISA_DATA[code];
  if (!d) return YEARS.map(() => null);
  const scores = d[type];
  return YEARS.map(y => {
    // Find surrounding PISA years and interpolate
    if (y < PISA_YEARS[0]) return null;
    const lastPisa = PISA_YEARS.filter(py => py <= y).pop();
    const nextPisa = PISA_YEARS.find(py => py > y);
    const i1 = PISA_YEARS.indexOf(lastPisa);
    const v1 = scores[i1];
    if (!nextPisa) return v1 != null ? rnd(v1, 0) : null;
    const i2 = PISA_YEARS.indexOf(nextPisa);
    const v2 = scores[i2];
    if (v1 == null || v2 == null) return v1 != null ? rnd(v1, 0) : null;
    const t = (y - lastPisa) / (nextPisa - lastPisa);
    return rnd(v1 + t * (v2 - v1), 0);
  });
}

