function applyFallback(codes, topicId, fallbackMap) {
  codes.forEach(c => {
    if (!appState.data[c]) appState.data[c] = {};
    if (fallbackMap[c] && (!appState.data[c][topicId] || appState.data[c][topicId].every(v => v == null))) {
      appState.data[c][topicId] = fallbackMap[c];
    }
  });
}

